FILE: app/src/set-share.ts
```ts
import type { AnimationManager, AnimationGroup } from "@babylonjs/lite";
import { removeAnimationTask } from "@babylonjs/lite";

export function setShareNow(manager: AnimationManager, group: AnimationGroup, share: number): void {
    group.weight = share;
    const tasks = manager.animations;
    for (let i = tasks.length - 1; i >= 0; i--) {
        const task = tasks[i] as any;
        if (task._group === group || task.group === group) {
            removeAnimationTask(manager, tasks[i]);
        }
    }
}
```

I set `group.weight` directly so the value is in place before the next update, then swept `manager.animations` backwards and removed any task that holds a reference to this group (checked `_group` and `group`), which kills the in-flight fade for this group while leaving other groups' fades untouched. The one thing I'm not certain of is the exact property name the fade task uses to store its target group; I covered the two most likely names (`_group`, `group`) based on the library's underscore-prefixed internal-property convention, but if the implementation uses a different name the old fade would survive and overwrite the weight on the next tick.
